const allRecords = $('2. Get Video Processing Records').all();
const startedAt = new Date().toISOString();
const results = [];

for (const record of allRecords) {
  const item = record.json;

  let heygenVideoId = (item['HeyGen_Video_ID'] || '').trim();

  if (!heygenVideoId) {
    const notes = item['Reel_Notes'] || '';
    const matchA = notes.match(/HeyGen Job ID:\s*([\w-]+)/);
    const matchB = notes.match(/Job ID:\s*([\w-]+)/);
    const matchC = notes.match(/([a-f0-9]{32,})/);
    heygenVideoId = (matchA || matchB || matchC || [])[1] || '';
  }

  if (!heygenVideoId) {
    results.push({ json: {
      skip: true,
      started_at: startedAt,
      record_id: item.id,
      topic: item['Topic'] || '',
      reason: 'No HeyGen ID found'
    }});
    continue;
  }

  results.push({ json: {
    skip: false,
    started_at: startedAt,
    record_id: item.id,
    heygen_video_id: heygenVideoId,
    topic: item['Topic'] || '',
    platform: item['Platform'] || '',
    content_type: item['Content Type'] || '',
    priority_score: item['Priority_Score'] || 0
  }});
}

return results;

const response = $input.item.json;

// Node 4 (Has HeyGen ID?) drops skip:true items before this node, so $itemIndex here
// indexes the POST-filter subset. Rebuild that exact subset (skip===false) in order and
// index into it. NEVER index into node 3's pre-filter array — that writes video URLs to
// the wrong records.
const survivors = $('3. Extract HeyGen Job ID').all().filter(r => r.json && r.json.skip === false);
const sourceData = survivors[$itemIndex]?.json || {};

if (!sourceData.record_id) {
  return { json: { skip: true, is_complete: false, is_failed: false, reason: 'No matching source record at survivor index ' + $itemIndex } };
}

// Hard guard: HeyGen echoes the video id. If the source record has no id, or the echoed id
// does not match it, write nothing — fall through as still-processing and re-poll next cycle.
const echoedId = response.data?.id || '';
if (!sourceData.heygen_video_id || (echoedId && echoedId !== sourceData.heygen_video_id)) {
  return { json: { skip: true, record_id: sourceData.record_id, started_at: sourceData.started_at || '', heygen_video_id: sourceData.heygen_video_id || '', is_complete: false, is_failed: false, reason: 'HeyGen ID mismatch: response ' + echoedId + ' != source ' + (sourceData.heygen_video_id || '(none)') } };
}

const isDataNull = response.data === null || response.data === undefined;
const status = isDataNull ? 'failed' : (response.data?.status || 'pending');
const videoUrl = response.data?.video_url || '';

// Only trust HeyGen response — no stale detection based on record age
const isComplete = status === 'completed';
const isFailed = status === 'failed' || isDataNull;

return {
  json: {
    record_id: sourceData.record_id,
    started_at: sourceData.started_at || '',
    heygen_status: status,
    video_url: videoUrl,
    is_complete: isComplete,
    is_failed: isFailed,
    heygen_video_id: sourceData.heygen_video_id,
    topic: sourceData.topic
  }
};

const parsed = $input.item.json;
const recId = parsed.record_id || '';
const shortId = recId ? recId.substring(0, 7) : 'norec';
let slug = String(parsed.topic || '').toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
if (slug.length > 40) { slug = slug.substring(0, 40); const cut = slug.lastIndexOf('-'); if (cut > 15) slug = slug.substring(0, cut); }
slug = slug.replace(/^-|-$/g, '') || 'avatar';
const genDate = $now.setZone('Asia/Manila').toFormat('yyyy-MM-dd');
const folderName = genDate + '_' + slug + '_' + shortId;
return { json: {
  record_id: recId,
  video_url: parsed.video_url,
  heygen_video_id: parsed.heygen_video_id,
  topic: parsed.topic || '',
  gen_date: genDate,
  short_id: shortId,
  folder_name: folderName,
  file_name: folderName + '.mp4'
}};

const fresh = $input.item.json || {};
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const ctx = $('7a. Restore Context for Drive').item.json;
const status = (f['Status'] || '').toString();
const existingUrl = (f['AI_Video_URL'] || '').toString();
const alreadyDone = status === 'Video Ready' || existingUrl.indexOf('drive.google.com') !== -1;
return { json: { ...ctx, already_done: alreadyDone, current_status: status, existing_video_url: existingUrl } };

const subfolderResponse = $input.item.json;
const ctx = $('7a. Restore Context for Drive').item.json;
return { json: {
  record_id: ctx.record_id,
  video_url: ctx.video_url,
  heygen_video_id: ctx.heygen_video_id,
  topic: ctx.topic,
  gen_date: ctx.gen_date,
  file_name: ctx.file_name,
  subfolder_id: subfolderResponse.id || ''
}};

const driveResponse = $input.item.json;
const ctx = $('7c. Preserve Subfolder ID').item.json;
const fileId = driveResponse.id || '';
return { json: {
  record_id: ctx.record_id,
  heygen_video_id: ctx.heygen_video_id,
  drive_file_id: fileId,
  drive_url: fileId ? `https://drive.google.com/file/d/${fileId}/view?usp=sharing` : ''
}};

const ctx = $('7f. Extract Drive File ID').item.json;
return { json: {
  record_id: ctx.record_id,
  heygen_video_id: ctx.heygen_video_id,
  drive_file_id: ctx.drive_file_id,
  drive_url: ctx.drive_url
}};

const fresh = $input.item.json || {};
const d = $('7h. Restore After Permission').item.json;
let parsed = {};
try { parsed = $('6. Parse Status').item.json; } catch (e) {}

const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = '==============================';
const TAG = 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();

let triggered = '';
let runtime = 'unknown';
try {
  const raw = parsed.started_at || '';
  triggered = raw ? raw.substring(0, 16).replace('T', ' ') : '';
  const s = Date.parse(raw);
  if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; }
} catch (e) {}

const jobId = d.heygen_video_id || parsed.heygen_video_id || '';
const jobUrl = jobId ? 'https://app.heygen.com/videos/' + jobId : '';
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

// HG-2: WF06 no longer completes renders, so the ratio and duration lines it used to write are built here.
const ratioRaw = f ? f.Ratio : '';
const ratio = (ratioRaw && typeof ratioRaw === 'object') ? (ratioRaw.name || '') : (ratioRaw || '');
const wpm = 150;
const words = String((f && f.Script) || '').split(/\s+/).filter(w => w.length > 0).length;
const estSecs = words > 0 ? Math.round(words / wpm * 60) : 0;
const mmss = (sec) => Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0');
const estLine = estSecs > 0 ? ('\nEstimated duration: ' + mmss(estSecs) + ' (' + words + ' words at ' + wpm + ' wpm)') : '';
const placement = estSecs > 0 ? ('\nEdit placement: base track, 0:00 - ' + mmss(estSecs)) : '\nEdit placement: base track, starts at 0:00';

const block = sep + '\n' + TAG
  + '\nTriggered: ' + triggered
  + '\nUpdated: ' + stamp
  + '\nRun time: ' + runtime
  + '\nStage: Complete'
  + '\nHeyGen Job ID: ' + jobId
  + (jobUrl ? '\nHeyGen Task URL: ' + jobUrl : '')
  + (ratio ? '\nRatio: ' + ratio : '')
  + estLine
  + placement
  + '\nDrive: ' + (d.drive_url || '');

return { json: { ...d, reel_notes_final: (base ? base + '\n\n' : '') + block } };

